    {
      "card_ids": ["C04"],
      "claim": "Encainide oral bioavailability in normal subjects was 32 ± 7%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Pivampicillin absolute bioavailability was 89% from capsules, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Benazepril oral bioavailability was >37%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values well above 20% (mostly 30–100%), and none fall below the threshold. The query's modified-release formulation would not be expected to reduce the extent of absorption below 20%; therefore the prediction is high.",
  "evidence_gaps": [
    "No direct bioavailability record for the exact query molecule, though the structure corresponds to diltiazem and all high-transfer analogues support F ≥ 20%.",
    "Modified-release formulation may alter absorption rate but not necessarily extent; no specific modified-release bioavailability data for the query were provided."
  ],
